/**
 * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.
 *
 * Must call (do not reimplement): shouldFilterArchived
 */
import { eq, isNull } from "drizzle-orm";
import { shouldFilterArchived } from "@/lib/soft-delete";
import type { ArchiveScope, OrgId } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

const CURSOR_SEPARATOR = "|";

/**
 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
 * sort value alongside the id is what lets `listX` resume from a stable point
 * even when two rows share a timestamp.
 */
export function encodeCursor(id: string, sortValue: string): string {
  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
    "base64url",
  );
}

export function decodeCursor(
  cursor: string,
): { id: string; sortValue: string } | null {
  let decoded: string;
  try {
    decoded = Buffer.from(cursor, "base64url").toString("utf8");
  } catch {
    return null;
  }

  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;

  return {
    sortValue: decoded.slice(0, separatorAt),
    id: decoded.slice(separatorAt + 1),
  };
}

/**
 * The tenant predicate. Every repository read and write composes this — a
 * query that does not mention `org_id` is a cross-tenant leak waiting to
 * happen, so this is the only sanctioned way to express it.
 */
export function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {
  return eq(column, orgId);
}

/**
 * The soft-delete predicate, or `undefined` when the caller explicitly asked
 * for archived rows. The `includeArchived` decision itself lives in
 * `shouldFilterArchived()` so it cannot drift per repository.
 */
export function livePredicate(
  column: SQLiteColumn,
  scope: ArchiveScope,
): SQL | undefined {
  return shouldFilterArchived(scope) ? isNull(column) : undefined;
}

/**
 * Project rows: cursor listing, slug/key uniqueness, soft delete and restore.
 *
 * Must call (do not reimplement): archivePatch, restorePatch, shouldFilterArchived, uniqueSlug
 */
import { and, count, desc, eq, isNotNull, like, lt, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import {
  archivePatch,
  restorePatch,
  shouldFilterArchived,
} from "@/lib/soft-delete";
import { getDb, issues, projects } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toProject } from "./_mappers";
import type {
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { ArchiveScope, OrgId, Page, ProjectId } from "@/types/common";
import type { Project, ProjectStats } from "@/types/project";

export async function findProjectById(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project | null> {
  const row = getDb()
    .select()
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();
  return row ? toProject(row) : null;
}

export async function findProjectBySlug(
  orgId: OrgId,
  slug: string,
): Promise<Project | null> {
  const row = getDb()
    .select()
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.slug, slug)))
    .get();
  return row ? toProject(row) : null;
}

export async function listProjects(
  input: ListProjectsInput,
): Promise<Page<Project>> {
  const db = getDb();
  const sort = { sortColumn: projects.createdAt, idColumn: projects.id };

  // The rows and the total must agree on the archive scope, so normalise the
  // filter's loose `includeArchived` into one `ArchiveScope` up front.
  const scope: ArchiveScope = shouldFilterArchived(input)
    ? {}
    : { includeArchived: true };

  const filters = compact(
    orgPredicate(projects.orgId, input.orgId),
    livePredicate(projects.archivedAt, scope),
    input.status === undefined ? undefined : eq(projects.status, input.status),
    input.query === undefined
      ? undefined
      : like(projects.name, `%${input.query}%`),
  );

  const total = db
    .select({ value: count() })
    .from(projects)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(projects)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(projects.createdAt), desc(projects.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(rows, input.limit, total?.value ?? 0, toProject, (row) => ({
    id: row.id,
    sortValue: row.createdAt,
  }));
}

/** Counts live projects by default; the `projects` quota reads this. */
export async function countProjects(
  orgId: OrgId,
  scope: ArchiveScope = {},
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(projects)
    .where(
      and(
        ...compact(
          orgPredicate(projects.orgId, orgId),
          livePredicate(projects.archivedAt, scope),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertProject(
  input: CreateProjectInput,
): Promise<Project> {
  const taken = await listTakenProjectSlugs(input.orgId);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(projects)
    .values({
      id: newId(),
      orgId: input.orgId,
      name: input.name,
      slug,
      key: input.key,
      description: input.description,
      visibility: input.visibility,
      status: "active",
      leadId: input.leadId,
      color: input.color,
      startsAt: null,
      targetDate: input.targetDate,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toProject(row);
}

export async function updateProject(
  input: UpdateProjectInput,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set({
      ...(input.name === undefined ? {} : { name: input.name }),
      ...(input.description === undefined
        ? {}
        : { description: input.description }),
      ...(input.visibility === undefined
        ? {}
        : { visibility: input.visibility }),
      ...(input.status === undefined ? {} : { status: input.status }),
      ...(input.leadId === undefined ? {} : { leadId: input.leadId }),
      ...(input.color === undefined ? {} : { color: input.color }),
      ...(input.targetDate === undefined
        ? {}
        : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(projects.orgId, input.orgId),
        eq(projects.id, input.projectId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Project ${input.projectId} not found`);
  return toProject(row);
}

export async function archiveProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set(archivePatch())
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .returning()
    .get();

  if (!row) throw new Error(`Project ${projectId} not found`);
  return toProject(row);
}

export async function restoreProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set(restorePatch())
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .returning()
    .get();

  if (!row) throw new Error(`Project ${projectId} not found`);
  return toProject(row);
}

/** Includes archived slugs — a restored project must not collide. */
export async function listTakenProjectSlugs(
  orgId: OrgId,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: projects.slug })
    .from(projects)
    .where(orgPredicate(projects.orgId, orgId))
    .all();
  return rows.map((row) => row.slug);
}

/** Open/closed/overdue counters plus the last write, for the project card. */
export async function getProjectStats(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ProjectStats> {
  const db = getDb();
  const scope = and(
    orgPredicate(issues.orgId, orgId),
    eq(issues.projectId, projectId),
    ...compact(livePredicate(issues.archivedAt, {})),
  );

  const closed = db
    .select({ value: count() })
    .from(issues)
    .where(and(scope, eq(issues.status, "done")))
    .get();

  const all = db.select({ value: count() }).from(issues).where(scope).get();

  const overdue = db
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        scope,
        isNotNull(issues.dueAt),
        lt(issues.dueAt, toIsoTimestamp(new Date())),
      ),
    )
    .get();

  const lastActivity = db
    .select({ value: sql<string | null>`max(${issues.updatedAt})` })
    .from(issues)
    .where(scope)
    .get();

  const closedCount = closed?.value ?? 0;

  return {
    projectId,
    openIssues: (all?.value ?? 0) - closedCount,
    closedIssues: closedCount,
    overdueIssues: overdue?.value ?? 0,
    lastActivityAt:
      lastActivity?.value == null ? null : toIsoTimestamp(lastActivity.value),
  };
}

/**
 * Per-user, per-kind delivery matrix consulted before every fan-out.
 */
import { and, eq } from "drizzle-orm";
import { getDb, notificationPreferences } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { brandId, toPreference } from "./_mappers";
import type { UpdateNotificationPreferenceInput } from "@/schemas/notification";
import type { OrgId, UserId } from "@/types/common";
import type {
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export async function listPreferences(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly NotificationPreference[]> {
  const rows = getDb()
    .select()
    .from(notificationPreferences)
    .where(
      and(
        orgPredicate(notificationPreferences.orgId, orgId),
        eq(notificationPreferences.userId, userId),
      ),
    )
    .all();
  return rows.map(toPreference);
}

/**
 * `null` means "no explicit row" — the fan-out then falls back to the default
 * channel set rather than treating the absence as "everything off".
 */
export async function getPreference(
  orgId: OrgId,
  userId: UserId,
  kind: NotificationKind,
): Promise<NotificationPreference | null> {
  const row = getDb()
    .select()
    .from(notificationPreferences)
    .where(
      and(
        orgPredicate(notificationPreferences.orgId, orgId),
        eq(notificationPreferences.userId, userId),
        eq(notificationPreferences.kind, kind),
      ),
    )
    .get();
  return row ? toPreference(row) : null;
}

export async function upsertPreference(
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  const row = getDb()
    .insert(notificationPreferences)
    .values({
      orgId: input.orgId,
      userId: input.userId,
      kind: input.kind,
      inApp: input.inApp,
      email: input.email,
      digestOnly: input.digestOnly,
    })
    .onConflictDoUpdate({
      target: [
        notificationPreferences.orgId,
        notificationPreferences.userId,
        notificationPreferences.kind,
      ],
      set: {
        inApp: input.inApp,
        email: input.email,
        digestOnly: input.digestOnly,
      },
    })
    .returning()
    .get();

  return toPreference(row);
}

/** Distinct users with at least one `digestOnly` preference in this org. */
export async function listDigestSubscribers(
  orgId: OrgId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .selectDistinct({ userId: notificationPreferences.userId })
    .from(notificationPreferences)
    .where(
      and(
        orgPredicate(notificationPreferences.orgId, orgId),
        eq(notificationPreferences.digestOnly, true),
      ),
    )
    .all();

  return rows.map((row) => brandId<UserId>(row.userId));
}

